import React, { useState, useEffect } from 'react';
import { authAPI } from '../utils/api';

export default function ChangePasswordModal({ onClose }) {
  const [step, setStep] = useState('google'); // google or password
  const [form, setForm] = useState({ current: '', new: '', confirm: '' });
  const [error, setError]   = useState('');
  const [success, setSuccess] = useState('');
  const [busy, setBusy]     = useState(false);
  const [googleToken, setGoogleToken] = useState('');

  useEffect(() => {
    // Load Google Sign-In script
    window.google?.accounts?.id?.initialize({
      client_id: '728649639944-g3l5b0u6c5j8j5l9j5l9j5l9j5l9j5l9.apps.googleusercontent.com', // Replace with your Google Client ID
      callback: handleGoogleResponse,
    });
  }, []);

  const handleGoogleResponse = async (response) => {
    if (response.credential) {
      setGoogleToken(response.credential);
      setError('');
      setStep('password');
    } else {
      setError('Google authentication failed.');
    }
  };

  const renderGoogleButton = () => {
    if (window.google?.accounts?.id) {
      setTimeout(() => {
        window.google.accounts.id.renderButton(
          document.getElementById('google-signin-btn'),
          { 
            type: 'standard',
            size: 'large',
            theme: 'filled_blue',
            width: '300'
          }
        );
      }, 0);
    }
  };

  useEffect(() => {
    if (step === 'google') {
      renderGoogleButton();
    }
  }, [step]);

  const submit = async (e) => {
    e.preventDefault();
    setError(''); setSuccess('');
    if (form.new !== form.confirm) { setError('New passwords do not match.'); return; }
    if (!googleToken) { setError('Google authentication required.'); return; }

    setBusy(true);
    try {
      await authAPI.changePassword({ 
        current: form.current, 
        new: form.new,
        googleToken: googleToken 
      });
      setSuccess('Password changed!');
      setTimeout(onClose, 1400);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed.');
    } finally { setBusy(false); }
  };

  return (
    <div className="overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-head">
          <span className="modal-title">🔑 Change Password</span>
          <button className="btn btn-outline btn-sm" onClick={onClose}>✕</button>
        </div>

        {step === 'google' && (
          <div className="modal-body">
            <p style={{ textAlign: 'center', marginBottom: 20, color: 'var(--t2)' }}>
              For security, please verify with Google first
            </p>
            <div id="google-signin-btn" style={{ display: 'flex', justifyContent: 'center' }}></div>
            {error && <div className="alert a-err" style={{ marginTop: 16 }}>{error}</div>}
          </div>
        )}

        {step === 'password' && (
          <form onSubmit={submit}>
            <div className="modal-body">
              {error   && <div className="alert a-err">{error}</div>}
              {success && <div className="alert a-ok">{success}</div>}
              <div style={{ padding: 8, background: 'rgba(0,82,204,0.08)', borderRadius: 4, marginBottom: 16, fontSize: 12, color: 'var(--t2)' }}>
                ✅ Google verified
              </div>
              <div className="fg"><label className="lbl">Current Password</label>
                <input className="inp" type="password" required value={form.current} onChange={e => setForm(f=>({...f,current:e.target.value}))} /></div>
              <div className="fg"><label className="lbl">New Password</label>
                <input className="inp" type="password" required minLength={6} value={form.new} onChange={e => setForm(f=>({...f,new:e.target.value}))} /></div>
              <div className="fg"><label className="lbl">Confirm New Password</label>
                <input className="inp" type="password" required value={form.confirm} onChange={e => setForm(f=>({...f,confirm:e.target.value}))} /></div>
            </div>
            <div className="modal-foot">
              <button type="button" className="btn btn-outline" onClick={() => { setStep('google'); setGoogleToken(''); setForm({current:'',new:'',confirm:''}) }}>Back</button>
              <button type="submit" className="btn btn-navy" disabled={busy}>{busy ? 'Saving…' : 'Update'}</button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}
